3d\\u0435\\u0432\\u043e\\u0437\\u043c\\u043e\\u0436\\u043d\\u043e \\u2014 \\u043a\\u043e\\u0434\\u0430 \\u043d\\u0435\\u0442. \\u0412\\u0441\\u0451 \\u043d\\u0438\\u0436\\u0435 \\u2014 \\u0438\\u0437 \\u043f\\u0430\\u043c\\u044f\\u0442\\u0438 \\u043e \\u043f\\u0443\\u0431\\u043b\\u0438\\u0447\\u043d\\u043e\\u043c \\u0440\\u0435\\u043f\\u043e sp179/QvQ \\u0438 \\u043a\\u043e\\u043d\\u0444\\u0438\\u0433\\u0435 Phi-3-mini-4k-instruct, \\u0438 \\u044d\\u0442\\u043e **\\u043d\\u0435\\u043f\\u0440\\u043e\\u0432\\u0435\\u0440\\u0435\\u043d\\u043d\\u044b\\u0435 \\u0443\\u0442\\u0432\\u0435\\u0440\\u0436\\u0434\\u0435\\u043d\\u0438\\u044f, \\u043f\\u043e\\u0434\\u043b\\u0435\\u0436\\u0430\\u0449\\u0438\\u0435 \\u0432\\u0435\\u0440\\u0438\\u0444\\u0438\\u043a\\u0430\\u0446\\u0438\\u0438**, \\u0430 \\u043d\\u0435 \\u0432\\u044b\\u0432\\u043e\\u0434\\u044b \\u0438\\u0437 \\u0438\\u043d\\u0441\\u043f\\u0435\\u043a\\u0446\\u0438\\u0438:\\n- \\u041e\\u0444\\u0438\\u0446\\u0438\\u0430\\u043b\\u044c\\u043d\\u044b\\u0439 QuaRot \\u0441\\u0442\\u0440\\u043e\\u0438\\u043b\\u0441\\u044f \\u0432\\u043e\\u043a\\u0440\\u0443\\u0433 LLaMA-\\u043f\\u043e\\u0434\\u043e\\u0431\\u043d\\u044b\\u0445 \\u043c\\u043e\\u0434\\u0435\\u043b\\u0435\\u0439 (LLaMA-2/3, Mistral) \\u0441 \\u0441\\u043e\\u0431\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u044b\\u043c\\u0438 CUDA-\\u044f\\u0434\\u0440\\u0430\\u043c\\u0438; Phi-3 \\u0432 \\u043e\\u0444\\u0438\\u0446\\u0438\\u0430\\u043b\\u044c\\u043d\\u043e\\u043c \\u043c\\u0430\\u0442\\u043f\\u0435\\u0434\\u0438\\u0438, \\u043d\\u0430\\u0441\\u043a\\u043e\\u043b\\u044c\\u043a\\u043e \\u043c\\u043d\\u0435 \\u0438\\u0437\\u0432\\u0435\\u0441\\u0442\\u043d\\u043e, \\u043d\\u0435\\u0442 \\u2192 \\u0441\\u0442\\u0430\\u0442\\u0443\\u0441 \\u043f\\u043e\\u0434\\u0434\\u0435\\u0440\\u0436\\u043a\\u0438: **unknown/\\u0432\\u0435\\u0440\\u043e\\u044f\\u0442\\u043d\\u043e \\u00ab\\u043d\\u0435\\u0442 \\u0438\\u0437 \\u043a\\u043e\\u0440\\u043e\\u0431\\u043a\\u0438\\u00bb**.\\n- \\u0422\\u043e\\u0447\\u0435\\u0447\\u043d\\u044b\\u0435 \\u0440\\u0438\\u0441\\u043a\\u0438, \\u043a\\u043e\\u0442\\u043e\\u0440\\u044b\\u0435 \\u043d\\u0430\\u0434\\u043e \\u043f\\u0440\\u043e\\u0432\\u0435\\u0440\\u0438\\u0442\\u044c \\u043f\\u0435\\u0440\\u0432\\u044b\\u043c \\u0434\\u0435\\u043b\\u043e\\u043c \\u043f\\u0440\\u0438 \\u043f\\u043e\\u044f\\u0432\\u043b\\u0435\\u043d\\u0438\\u0438 \\u043a\\u043e\\u0434\\u0430: (i) head_dim=96 \\u0443 Phi-3-mini (hidden 3072 / 32 \\u0433\\u043e\\u043b\\u043e\\u0432\\u044b) \\u2014 **\\u043d\\u0435 \\u0441\\u0442\\u0435\\u043f\\u0435\\u043d\\u044c \\u0434\\u0432\\u043e\\u0439\\u043a\\u0438**, \\u0430 FWHT \\u0438 online-Hadamard \\u0434\\u043b\\u044f down_proj \\u0432 QuaRot \\u043e\\u0431\\u044b\\u0447\\u043d\\u043e \\u0442\\u0440\\u0435\\u0431\\u0443\\u044e\\u0442 \\u0441\\u0442\\u0435\\u043f\\u0435\\u043d\\u044c 2 \\u2192 \\u043d\\u0443\\u0436\\u043d\\u0430 padding-\\u0434\\u043e-128 \\u0438\\u043b\\u0438 \\u0431\\u043b\\u043e\\u0447\\u043d\\u043e-\\u0434\\u0438\\u0430\\u0433\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u0430\\u044f \\u0440\\u043e\\u0442\\u0430\\u0446\\u0438\\u044f; (ii) \\u0443 Phi-3 mlp_bias=true (bias \\u0432 MLP), \\u0442\\u043e\\u0433\\u0434\\u0430 \\u043a\\u0430\\u043a pipeline QuaRot \\u0432\\u044b\\u0447\\u0438\\u0442\\u0430\\u0435\\u0442/\\u0441\\u043b\\u0438\\u0432\\u0430\\u0435\\u0442 bias \\u2014 \\u043d\\u0430\\u0434\\u043e \\u043f\\u0440\\u043e\\u0432\\u0435\\u0440\\u0438\\u0442\\u044c \\u043e\\u0431\\u0440\\u0430\\u0431\\u043e\\u0442\\u043a\\u0443; (iii) num_key_value_heads=32, \\u0442.\\u0435. MHA \\u0431\\u0435\\u0437 GQA \\u2014 \\u044d\\u0442\\u043e \\u0443\\u043f\\u0440\\u043e\\u0449\\u0435\\u043d\\u0438\\u0435, \\u0430 \\u043d\\u0435 \\u0440\\u0438\\u0441\\u043a; (iv) HF-\\u043e\\u0431\\u0451\\u0440\\u0442\\u043a\\u0430 \\u00abrotation-\\u043a\\u0430\\u043a-\\u043e\\u0431\\u044b\\u0447\\u043d\\u044b\\u0435-Linear\\u00bb vs CUDA-\\u044f\\u0434\\u0440\\u0430: \\u044f\\u04