f\\u0447\\u0435\\u0435\\u043a, \\u0433\\u0434\\u0435 QuaRot-off \\u2014 \\u0430\\u0431\\u043b\\u044f\\u0446\\u0438\\u044f, \\u0438\\u0437\\u043e\\u043b\\u0438\\u0440\\u0443\\u044e\\u0449\\u0430\\u044f \\u0432\\u043a\\u043b\\u0430\\u0434 \\u0440\\u043e\\u0442\\u0430\\u0446\\u0438\\u0438 \\u043e\\u0442 \\u043a\\u0432\\u0430\\u043d\\u0442\\u0438\\u0437\\u0430\\u0442\\u043e\\u0440\\u0430. \\u041f\\u043b\\u044e\\u0441 \\u043a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u044c\\u043d\\u044b\\u0435 \\u0442\\u043e\\u0447\\u043a\\u0438:\\n- **FP16/BF16 baseline** (\\u043e\\u0431\\u044f\\u0437\\u0430\\u0442\\u0435\\u043b\\u044c\\u043d\\u0430\\u044f);\\n- **rotation-only, no-quant** (FP16 + \\u0432\\u0441\\u0435 Hadamard-\\u0440\\u043e\\u0442\\u0430\\u0446\\u0438\\u0438) \\u2014 sanity-\\u0447\\u0435\\u043a \\u0447\\u0438\\u0441\\u043b\\u0435\\u043d\\u043d\\u043e\\u0439 \\u043a\\u043e\\u0440\\u0440\\u0435\\u043a\\u0442\\u043d\\u043e\\u0441\\u0442\\u0438 \\u0440\\u043e\\u0442\\u0430\\u0446\\u0438\\u0439 \\u043d\\u0430 Phi-3: \\u0434\\u0440\\u0435\\u0439\\u0444 \\u043b\\u043e\\u0433\\u0438\\u0442\\u043e\\u0432/KL \\u043a baseline \\u0434\\u043e\\u043b\\u0436\\u043d\\u044b \\u0431\\u044b\\u0442\\u044c ~\\u043c\\u0430\\u0448\\u0438\\u043d\\u043d\\u043e\\u0439 \\u0442\\u043e\\u0447\\u043d\\u043e\\u0441\\u0442\\u0438, \\u0438\\u043d\\u0430\\u0447\\u0435 \\u0432\\u0441\\u044f \\u0441\\u0435\\u0442\\u043a\\u0430 \\u043d\\u0435\\u0434\\u043e\\u0441\\u0442\\u043e\\u0432\\u0435\\u0440\\u043d\\u0430;\\n- \\u043e\\u043f\\u0446\\u0438\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u043e W4A4 (online Hadamard \\u043d\\u0430 \\u0430\\u043a\\u0442\\u0438\\u0432\\u0430\\u0446\\u0438\\u044f\\u0445) \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u0434\\u043b\\u044f W4 \\u043a\\u0430\\u043a \\u043c\\u0430\\u0440\\u043a\\u0435\\u0440 \\u00ab\\u043f\\u043e\\u043b\\u043d\\u043e\\u0433\\u043e QuaRot\\u00bb \\u2014 \\u0432\\u043d\\u0435 \\u043e\\u0441\\u043d\\u043e\\u0432\\u043d\\u043e\\u0439 \\u0441\\u0435\\u0442\\u043a\\u0438, \\u043f\\u0440\\u0438 \\u043d\\u0430\\u043b\\u0438\\u0447\\u0438\\u0438 \\u0431\\u044e\\u0434\\u0436\\u0435\\u0442\\u0430.\\n\\u0424\\u0438\\u043a\\u0441\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u044b\\u0435 hyperparams: group-size 128 \\u0434\\u043b\\u044f RTN/GPTQ (\\u043f\\u043e \\u043f\\u0440\\u0430\\u043a\\u0442\\u0438\\u043a\\u0435 QuaRot \\u2014 \\u043f\\u0440\\u043e\\u0432\\u0435\\u0440\\u0438\\u0442\\u044c \\u043f\\u043e \\u0442\\u0435\\u043c\\u0430\\u043c \\u0438\\u0441\\u0442\\u043e\\u0447\\u043d\\u0438\\u043a\\u0430), act-order/dampening \\u2014 \\u0435\\u0434\\u0438\\u043d\\u044b \\u0434\\u043b\\u044f \\u0432\\u0441\\u0435\\u0445 \\u044f\\u0447\\u0435\\u0435\\u043a, \\u0437\\u043d\\u0430\\u0447\\u0435\\u043d\\u0438\\u044f \\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u0443\\u044e\\u0442\\u0441\\u044f \\u0434\\u043e \\u0437\\u0430\\u043f\\u0443\\u0441\\u043a\\u0430.\\n\\n**\\u041f\\u0435\\u0440\\u043f\\u043b\\u0435\\u043a\\u0441\\u0438\\u044f (\\u043e\\u0441\\u044c 1):** \\u043e\\u0441\\u043d\\u043e\\u0432\\u043d\\u0430\\u044f \\u2014 WikiText-2 test, \\u043a\\u043e\\u043d\\u0442\\u0435\\u043a\\u0441\\u0442 **4096** (\\u043c\\u043e\\u0434\\u0435\\u043b\\u044c 4k-instruct; \\u0441\\u043a\\u043e\\u043b\\u044c\\u0437\\u044f\\u0449\\u0435\\u0435 \\u043e\\u043a\\u043d\\u043e \\u0431\\u0435\\u0437 \\u043f\\u0435\\u0440\\u0435\\u043a\\u0440\\u044b\\u0442\\u0438\\u044f, stride=seq_len), \\u043f\\u043e\\u0442\\u043e\\u043c\\u0443 \\u0447\\u0442\\u043e (\\u0430) \\u044d\\u0442\\u043e \\u043d\\u0430\\u0442\\u0438\\u0432\\u043d\\u044b\\u0439 \\u043a\\u043e\\u043d\\u0442\\u0435\\u043a\\u0441\\u0442 \\u043c\\u043e\\u0434\\u0435\\u043b\\u0438, (\\u0431) QuaRot \\u0432 \\u0441\\u0442\\u0430\\u0442\\u044c\\u0435 \\u043c\\u0451\\u0440\\u0438\\u0442 PPL \\u043d\\u0430 \\u0434\\u043b\\u0438\\u043d\\u043d\\u043e\\u043c \\u043a\\u043e\\u043d\\u0442\\u0435\\u043a\\u0441\\u0442\\u0435, \\u0433\\u0434\\u0435 outlier-\\u044d\\u0444\\u0444\\u0435\\u043a\\u0442\\u044b \\u0441\\u0438\\u043b\\u044c\\u043d\\u0435\\u0435. \\u041a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u044c\\u043d\\u044b\\u0439 \\u043f\\u0440\\u043e\\u0433\\u043e\\u043d \\u2014 C4 val \\u043f\\u0440\\u0438 2048 \\u0434\\u043b\\u044f \\u0441\\u043e\\u043f\\u043e\\u0441\\u0442\\u0430\\u0432\\u0438\\u043c\\u043e\\u0441\\u0442\\u0438 \\u0441 \\u0446\\u0438\\u0444\\u0440\\u0430\\u043c\\u0438 \\u0441\\u0442\\u0430\\u0442\\u044c\\u0438 (\\u0443\\u0440\\u043e\\u0432\\u0435\\u043d\\u044c cross-check, \\u043d\\u0435 \\u043e\\u0441\\u043d\\u043e\\u0432\\u043d\\u0430\\u044f \\u043e\\u0441\\u044c). \\u0421\\u0440\\u0430\\u0432\\u043d\\u0435\\u043d\\u0438\\u0435 \\u0441 512-\\u0442\\u043e\\u043a\\u0435\\u043d\\u043d\\u044b\\u043c \\u043e\\u043a\\u043d\\u043e\\u043c \\u2014 \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u0435\\u0441\\u043b\\u0438 \\u0431\\u044e\\u0434\\u0436\\u0435\\u0442 \\u043f\\u043e\\u0437\\u0432\\u043e\\u043b\\u0438\\u0442.\\n\\n**Zero-shot (\\u043e\\u0441\\u044c 2):** lm-evaluation-harness, loglikelihood-\\u0437\\u0430\\u0434\\u0430\\u0447\\u0438: **piqa, hellaswag, arc-easy, arc-challenge, arc-cloze?, winogrande, openbookqa** (\\u043c\\u0435\\u0442\\u0440\\u0438\\u043a\\u0430 acc, \\u0433\\u0434\\u0435 \\u0443\\u043c\\u0435\\u0441\\u0442\\u043d\\u043e acc_norm; \\u043f\\u043b\\u044e\\u0441 \\u0441\\u0440\\u0435\\u0434\\u043d\\u0438\\u0439 \\u043f\\u043e 5\\u20136 \\u0437\\u0430\\u0434\\u0430\\u0447\\u0430\\u043c). \\u0414\\u043b\\u044f instruct-\\u043c\\u043e\\u0434\\u0435\\u043b\\u0438 \\u2014 \\u0435\\u0434\\u0438\\u043d\\u044b\\u0439 \\u043f\\u0440\\u043e\\u043c\\u043f\\u0442-\\u0448\\u0430\\u0431\\u043b\\u043e\\u043d \\u0441 chat template, \\u0437\\u0430\\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u043e\\u0432\\u0430\\u0442\\u044c \\u0432 \\u043a\\u043e\\u043d\\u0444\\u0438\\u0433\\u0435. \\u0412\\u0442\\u043e\\u0440\\u0438\\u0447\\u043d\\u044b\\u0439 \\u0431\\u043b\\u043e\\u043a (only-if-budget): GSM8K (em, flexible-extract) \\u043a\\u043