\\u0435\\u0430\\u043b\\u044c\\u043d\\u044b\\u0439 \\u043f\\u0440\\u043e\\u0433\\u043e\\u043d \\u043f\\u0440\\u0435\\u0434\\u043f\\u043e\\u043b\\u0430\\u0433\\u0430\\u0435\\u0442 1\\u00d7GPU 80\\u0413\\u0411; \\u0432 \\u0442\\u0435\\u043a\\u0443\\u0449\\u0435\\u0439 \\u0441\\u0440\\u0435\\u0434\\u0435 \\u0432\\u043e\\u0437\\u043c\\u043e\\u0436\\u0435\\u043d \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d \\u0438 \\u0441\\u0442\\u0430\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0435 \\u043f\\u0440\\u043e\\u0432\\u0435\\u0440\\u043a\\u0438\"], \"uncertainties\": [\"\\u041f\\u043e\\u0434\\u0434\\u0435\\u0440\\u0436\\u0438\\u0432\\u0430\\u0435\\u0442 \\u043b\\u0438 \\u043e\\u0444\\u0438\\u0446\\u0438\\u0430\\u043b\\u044c\\u043d\\u044b\\u0439 \\u043a\\u043e\\u0434 QuaRot Phi-3-mini \\u2014 unknown (\\u043a\\u043e\\u0434\\u0430 \\u043d\\u0435\\u0442 \\u0432 \\u0441\\u0440\\u0435\\u0434\\u0435; \\u0432\\u0435\\u0440\\u043e\\u044f\\u0442\\u043d\\u043e \\u043d\\u0435\\u0442)\", \"\\u0422\\u043e\\u0447\\u043d\\u044b\\u0439 eval-\\u043f\\u0440\\u043e\\u0442\\u043e\\u043a\\u043e\\u043b \\u0441\\u0442\\u0430\\u0442\\u044c\\u0438 (PPL seq-len, \\u043d\\u0430\\u0431\\u043e\\u0440 zero-shot, \\u0440\\u0435\\u043f\\u043e\\u0440\\u0442\\u0438\\u0440\\u0443\\u044e\\u0442\\u0441\\u044f \\u043b\\u0438 W6/W8) \\u2014 unknown \\u0434\\u043e \\u0437\\u0430\\u043f\\u0440\\u043e\\u0441\\u0430 \\u043f\\u043e \\u0442\\u0435\\u043c\\u0430\\u043c neurips2024/94328\", \"\\u0427\\u0438\\u0441\\u043b\\u0435\\u043d\\u043d\\u0430\\u044f \\u043a\\u043e\\u0440\\u0440\\u0435\\u043a\\u0442\\u043d\\u043e\\u0441\\u0442\\u044c Hadamard-\\u0440\\u043e\\u0442\\u0430\\u0446\\u0438\\u0439 \\u043f\\u0440\\u0438 head_dim=96 \\u2014 \\u043a\\u043b\\u044e\\u0447\\u0435\\u0432\\u043e\\u0439 \\u0442\\u0435\\u0445\\u043d\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0439 \\u0440\\u0438\\u0441\\u043a, \\u0442\\u0440\\u0435\\u0431\\u0443\\u0435\\u0442 \\u0442\\u0435\\u0441\\u0442\\u0430 \\u044d\\u043a\\u0432\\u0438\\u0432\\u0430\\u043b\\u0435\\u043d\\u0442\\u043d\\u043e\\u0441\\u0442\\u0438\", \"\\u041e\\u0431\\u0440\\u0430\\u0431\\u043e\\u0442\\u043a\\u0430 mlp_bias \\u0432 QuaRot-\\u043f\\u0430\\u0439\\u043f\\u043b\\u0430\\u0439\\u043d\\u0435 \\u0434\\u043b\\u044f Phi-3 \\u2014 unknown\", \"\\u0411\\u044e\\u0434\\u0436\\u0435\\u0442 \\u0432\\u044b\\u0447\\u0438\\u0441\\u043b\\u0435\\u043d\\u0438\\u0439 \\u0440\\u0435\\u0430\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u043f\\u0440\\u043e\\u0433\\u043e\\u043d\\u0430 researcher'\\u043e\\u043c \\u043d\\u0435\\u0438\\u0437\\u0432\\u0435\\u0441\\u0442\\u0435\\u043d \\u2014 \\u043f\\u043b\\u0430\\u043d \\u0441\\u043e\\u0434\\u0435\\u0440\\u0436\\u0438\\u0442 \\u044f\\u0432\\u043d\\u0443\\u044e \\u043e\\u0447\\u0435\\u0440\\u0435\\u0434\\u044c \\u0441\\u043e\\u043a\\u0440\\u0430\\u0449\\u0435\\u043d\\u0438\\u0439\"]}", "kind": "ActionEvent"}
