u043a\\u043e \\u043e\\u0431\\u044a\\u044f\\u0441\\u043d\\u044f\\u0435\\u0442 \\u0440\\u0435\\u0437\\u0443\\u043b\\u044c\\u0442\\u0430\\u0442\\u00bb):**\\n- E1. QuaRot-off RTN/GPTQ \\u00d7 {W4,W6,W8} (6 \\u044f\\u0447\\u0435\\u0435\\u043a) \\u2014 \\u0438\\u0437\\u043e\\u043b\\u044f\\u0446\\u0438\\u044f \\u0432\\u043a\\u043b\\u0430\\u0434\\u0430 \\u0440\\u043e\\u0442\\u0430\\u0446\\u0438\\u0438 \\u043e\\u0442 \\u043a\\u0432\\u0430\\u043d\\u0442\\u0438\\u0437\\u0430\\u0442\\u043e\\u0440\\u0430;\\n- E2. rotation-only no-quant \\u2014 \\u0437\\u0430\\u0441\\u0447\\u0438\\u0442\\u044b\\u0432\\u0430\\u0435\\u0442\\u0441\\u044f \\u043a\\u0430\\u043a **\\u0433\\u0435\\u0439\\u0442** (\\u0440\\u0430\\u0437\\u0434\\u0435\\u043b 3), \\u0432 \\u0442\\u0430\\u0431\\u043b\\u0438\\u0446\\u0443 \\u0440\\u0435\\u0437\\u0443\\u043b\\u044c\\u0442\\u0430\\u0442\\u0430 \\u043d\\u0435 \\u043f\\u043e\\u043f\\u0430\\u0434\\u0430\\u0435\\u0442;\\n- E3. W4A4 (online Hadamard \\u043d\\u0430 \\u0430\\u043a\\u0442\\u0438\\u0432\\u0430\\u0446\\u0438\\u044f\\u0445) \\u2014 \\u043c\\u0430\\u0440\\u043a\\u0435\\u0440 \\u00ab\\u043f\\u043e\\u043b\\u043d\\u043e\\u0433\\u043e QuaRot\\u00bb \\u043d\\u0430 W4; \\u0440\\u0438\\u0441\\u043a: \\u0437\\u0430\\u0432\\u044f\\u0437\\u0430\\u043d \\u043d\\u0430 \\u0441\\u0442\\u0435\\u043f\\u0435\\u043d\\u044c-2 dim, \\u0434\\u043b\\u044f head_dim=96 \\u26a0\\ufe0f \\u043c\\u043e\\u0436\\u0435\\u0442 \\u043f\\u043e\\u0442\\u0440\\u0435\\u0431\\u043e\\u0432\\u0430\\u0442\\u044c \\u0442\\u0443 \\u0436\\u0435 \\u0431\\u043b\\u043e\\u0447\\u043d\\u0443\\u044e \\u0430\\u0434\\u0430\\u043f\\u0442\\u0430\\u0446\\u0438\\u044e;\\n- E4. C4-val PPL @2048 \\u2014 \\u043a\\u0440\\u043e\\u0441\\u0441-\\u0447\\u0435\\u043a \\u0441\\u043e\\u043f\\u043e\\u0441\\u0442\\u0430\\u0432\\u0438\\u043c\\u043e\\u0441\\u0442\\u0438 \\u0441\\u043e \\u0441\\u0442\\u0430\\u0442\\u044c\\u0435\\u0439;\\n- E5. GSM8K (em, flexible-extract, greedy) \\u2014 \\u0447\\u0443\\u0432\\u0441\\u0442\\u0432\\u0438\\u0442\\u0435\\u043b\\u044c\\u043d\\u0430\\u044f \\u0433\\u0435\\u043d\\u0435\\u0440\\u0430\\u0442\\u0438\\u0432\\u043d\\u0430\\u044f \\u0437\\u0430\\u0434\\u0430\\u0447\\u0430.\\n\\n## 2. \\u041f\\u0440\\u043e\\u0442\\u043e\\u043a\\u043e\\u043b\\n\\n**\\u041c\\u043e\\u0434\\u0435\\u043b\\u044c.** microsoft/Phi-3-mini-4k-instruct. \\u041a\\u043e\\u043d\\u0444\\u0438\\u0433 \\u26a0\\ufe0f (\\u043f\\u043e \\u043f\\u0430\\u043c\\u044f\\u0442\\u0438, \\u043e\\u0431\\u044f\\u0437\\u0430\\u0442\\u0435\\u043b\\u0435\\u043d \\u0441\\u0432\\u0435\\u0440\\u043a\\u0430 \\u0441 config.json \\u0434\\u043e \\u0437\\u0430\\u043f\\u0443\\u0441\\u043a\\u0430): hidden=3072, 32 \\u0441\\u043b\\u043e\\u044f, 32 Q/32 KV \\u0433\\u043e\\u043b\\u043e\\u0432\\u044b (MHA \\u0431\\u0435\\u0437 GQA), head_dim=96, intermediate=8192, vocab=32064, attention_bias=false, **mlp_bias=true**. \\u041a\\u0432\\u0430\\u043d\\u0442\\u0443\\u044e\\u0442\\u0441\\u044f \\u0432\\u0441\\u0435 Linear (attention q/k/v/o, MLP gate/up/down); lm_head \\u043d\\u0435 \\u043a\\u0432\\u0430\\u043d\\u0442\\u0443\\u0435\\u0442\\u0441\\u044f (\\u0437\\u0430\\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u043e\\u0435 \\u0440\\u0435\\u0448\\u0435\\u043d\\u0438\\u0435).\\n\\n**\\u041a\\u0432\\u0430\\u043d\\u0442\\u0438\\u0437\\u0430\\u0442\\u043e\\u0440\\u044b (\\u043e\\u0431\\u0449\\u0438\\u0435 \\u0434\\u043b\\u044f \\u043e\\u0431\\u0435\\u0438\\u0445 \\u0432\\u0435\\u0442\\u043e\\u043a):** \\u0441\\u0438\\u043c\\u043c\\u0435\\u0442\\u0440\\u0438\\u0447\\u043d\\u044b\\u0439 \\u043a\\u0432\\u0430\\u043d\\u0442, **group-size 128**, per-group scale, \\u043e\\u0434\\u0438\\u043d\\u0430\\u043a\\u043e\\u0432\\u0430\\u044f \\u043a\\u0430\\u043b\\u0438\\u0431\\u0440\\u043e\\u0432\\u043a\\u0430, \\u043e\\u0434\\u0438\\u043d\\u0430\\u043a\\u043e\\u0432\\u044b\\u0439 \\u043d\\u0430\\u0431\\u043e\\u0440/seq-len eval. GPTQ: Hessian \\u0441 \\u043a\\u0430\\u043b\\u0438\\u0431\\u0440\\u043e\\u0432\\u043a\\u0438, damping=0.01 (\\u26a0\\ufe0f \\u043a\\u043e\\u043d\\u0432\\u0435\\u043d\\u0446\\u0438\\u044f, \\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043e \\u0434\\u043e \\u0437\\u0430\\u043f\\u0443\\u0441\\u043a\\u0430), act-order=off (\\u0434\\u0435\\u0442\\u0435\\u0440\\u043c\\u0438\\u043d\\u0438\\u0437\\u043c \\u0438 \\u043f\\u0440\\u043e\\u0441\\u0442\\u043e\\u0442\\u0430; \\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043e), fp32-\\u0430\\u043a\\u043a\\u0443\\u043c\\u0443\\u043b\\u044f\\u0446\\u0438\\u044f. RTN: per-group round-to-nearest \\u043d\\u0430 \\u0440\\u043e\\u0442\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u044b\\u0445 \\u0432\\u0435\\u0441\\u0430\\u0445; \\u043a\\u0430\\u043b\\u0438\\u0431\\u0440\\u043e\\u0432\\u043a\\u0430 RTN \\u043d\\u0435 \\u043d\\u0443\\u0436\\u043d\\u0430, \\u043d\\u043e \\u0442\\u043e\\u0442 \\u0436\\u0435 \\u043d\\u0430\\u0431\\u043e\\u0440 \\u0440\\u0435\\u0437\\u0435p\\u0432\\u0438\\u0440\\u0443\\u0435\\u0442\\u0441\\u044f \\u0434\\u043b\\u044f \\u0441\\u0442\\u0430\\u0442\\u0438\\u0441\\u0442\\u0438\\u043a \\u0430\\u043a\\u0442\\u0438\\u0432\\u0430\\u0446\\u0438\\u0439 (\\u0434\\u043b\\u044f E3).\\n\\n**\\u041a\\u0430\\u043b\\u0438\\u0431\\u0440\\u043e\\u0432\\u043a\\u0430 (\\u0434\\u043b\\u044f GPTQ):** C4, 128 \\u043f\\u043e\\u0441\\u043b\\u0435\\u0434\\u043e\\u0432\\u0430\\u0442\\u0435\\u043b\\u044c\\u043d\\u043e\\u0441\\u0442\\u0435\\u0439 \\u00d7 2048 \\u0442\\u043e\\u043a\\u0435\\u043d\\u043e\\u0432, seed=0, \\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u0443\\u0435\\u0442\\u0441\\u044f \\u043a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u044c\\u043d\\u043e\\u0439 \\u0441\\u0443\\u043c\\u043c\\u043e\\u0439. \\u26a0\\ufe0f \\u0414\\u043e\\u043f\\u0443\\u0449\\u0435\\u043d\\u0438\\u0435 \\u043f\\u043e \\u043a\\u043e\\u043d\\u0432\\u0435\\u043d\\u0446\\u0438\\u0438 QuaRot-\\u0441\\u0435\\u043c\\u0435\\u0439\\u0441\\u0442\\u0432\\u0430; \\u0442\\u043e\\u0447\\u043d\\u044b\\u0439 \\u043f\\u0440\\u043e\\u0442\\u043e\\u043a\\u043e\\u043b \\u0441\\u0442\\u0430\\u0442\\u044c\\u0438 \\u2014 unknown, \\u0443\\u0442\\u043e\\u0447\\u043d\\u044f\\u0435\\u0442\\u0441\\u044f \\u043f\\u043e \\u0442\\u0435\\u043c\\u0430\\u043c neurips2024/94328 (\\u0431\\u044e\\u0434\\u0436\\u0435\\u0442 6 \\u0432\\u043e\\u043f\\u0440\\u043e\\u0441\\u043e\\u0432: \\u043a\\u0430\\u043b\\u0438\\u0431\\u0440\\u043e\\u0432\\u043a\\u0430; PPL seq-len/\\u0434\\u0430\\u0442\\u0430\\u0441\\u0435\\u0442\\u044b; zero-shot \\u043d\\u0430\\u0431\\u043e\\u0440/\\u043c\\u0435\\u0442\\u0440\\u0438\\u043a\\u0438; group/bias-\\u043e\\u0431\\u0440\\u0430\\u0431\\u043e\\u0442\\u043a\\u0430; \\u0440\\u0435\\u043f\\u043e\\u0440\\u0442\\u044f\\u0442\\u0441\\u044f \\u043b\\u0438 W6/W8; \\u043f\\u0440\\u043e\\u0442\\u043e\\u043a\\u043e\\u043b \\u043f\\u043e\\u0432\\u0442\\u043e\\u0440\\u043e\\u0432).\\n\\n**Rotation-\\u0440\\u0435\\u0446\\u0435\\u043f\\u0442 \\u0438 \\u0430\\u0434\\u0430\\u043f\\u0442\\u0430\\u0446\\u0438\\u044f \\u043f\\u043e\\u0434 head_dim=96.** \\u041f\\u0435\\u0440\\u0435\\u043d\\u043e\\u0441\\u0438\\u043c R1 (embeddings\\u2192\\u0432\\u0445\\u043e\\u0434\\u044b \\u0441\\u043b\\u043e\\u0451\\u0432 / \\u0432\\u0445\\u043e\\u0434\\u044b \\u0433\\u043e\\u043b\\u043e\\u0432), R2 (q/k \\u043f\\u043e\\u0441\\u043b\\u0435 RoPE, online), R3 (V\\u2192o), R4 (\\u0432\\u0445\\u043e\\u0434\\u044b down_proj, online). \\u041f\\u0440\\u043e\\u0431\\u043b\\u0435\\u043c\\u0430: 96 \\u2014 \\u043d\\u0435 \\u0441\\u0442\\u0435\\u043f\\u0435\\u043d\\u044c 2, \\u043a\\u043b\\u0430\\u0441\\u0441\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0439 FWHT \\u043d\\u0435 \\u043f\\u0440\\u0438\\u043c\\u0435\\u043d\\u0438\\u043c. **\\u0420\\u0435\\u0448\\u0435\\u043d\\u0438\\u0435 \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d\\u0430:** \\u0431\\u043b\\u043e\\u0447\\u043d\\u043e-\\u0434\\u0438\\u0430\\u0433\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u0430\\u044f \\u043e\\u0440\\u0442\\u043e\\u0433\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u0430\\u044f \\u043c\\u0430\\u0442\\u0440\\u0438\\u0446\\u0430 H64\\u2295H32 (\\u0434\\u0432\\u0430 Hadamard-\\u0431\\u043b\\u043e\\u043a\\u0430) \\u043d\\u0430 \\u0432\\u0441\\u0435\\u0445 head_dim-\\u043f\\u043e\\u0437\\u0438\\u0446\\u0438\\u044f\\u0445; \\u043d\\u043e\\u0440\\u043c\\u0443 \\u0441\\u043e\\u0445\\u0440\\u0430\\u043d\\u044f\\u0435\\u0442, \\u043e\\u043d\\u043b\\u0430\\u0439\\u043d-\\u043f\\u0440\\u0438\\u043c\\u0435\\u043d\\u0435\\u043d\\u0438\\u0435 \\u0432\\u043e\\u0437\\u043c\\u043e\\u0436\\u043d\\u043e \\u0442\\u043e\\u0439 \\u0436\\u0435 \\u0431\\u043b\\u043e\\u0447\\u043d\\u043e\\u0439 \\u043c\\u0430\\u0442\\u0440\\u0438\\u0446\\u0435\\u0439. Fallback: \\u043f\\u043e\\u043b\\u043d\\u0430\\u044f 96\\u00d796 \\u043e\\u0440\\u0442\\u043e\\u0433\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u0430\\u044f \\u0447\\u0435\\u0440\\u0435\\u0437 QR \\u0433\\u0430\\u0443\\u0441\\u0441\\u043e\\u0432\\u043e\\u0439 \\u043c\\u0430\\u0442\\u0440\\u0438\\u0446\\u044b (\\u0442\\u0435\\u0440\\u044f\\u0435\\u0442\\u0441\\u044f self-\\u0438\\u043d\\u0432\\u0435\\u0440\\u0442\\u0438\\u0440\\u0443\\u0435\\u043c\\u043e\\u0441\\u0442\\u044c H \\u2192 \\u043b\\u043e\\u043c\\u0430\\u0435\\u0442 online-\\u0447\\u0430\\u0441\\u0442\\u044c,Acceptable \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u0434\\u043b\\u044f A16-\\u0432\\u0435\\u0442\\u043a\\u0438). Intermediate=8192 \\u2014 \\u0441\\u0442\\u0435\\u043f\\u0435\\u043d\\u044c 2, R4 \\u0431\\u0435\\u0437 \\u0430\\u0434\\u0430\\u043f\\u0442\\u0430\\u0446\\u0438\\u0438. \\u041a\\u043e\\u0440\\u0440\\u0435\\u043a\\u0442\\u043d\\u043e\\u0441\\u0442\\u044c\\u6574\\u4e2a \\u0440\\u0435\\u0446\\u0435\\u043f\\u0442\\u0430 \\u0434\\u043e\\u043a\\u0430\\u0437\\u044b\\u0432\\u0430\\u0435\\u0442\\u0441\\u044f \\u0433\\u0435\\u0439\\u0442\\u043e\\u043c G1, \\u0430 \\u043d\\u0435 \\u0432\\u0435\\u0440\\u043e\\u0439.\\n\\n**Perplexity.** WikiText-2 test, \\u043a\\u043e\\u043d\\u0442\\u0435\\u043a\\u0441\\u0442 4096, \\u0441\\u043a\\u043e\\u043b\\u044c\\u0437\\u044f\\u0449\\u0438\\u0435 **\\u043d\\u0435\\u043f\\u0435\\u0440\\u0435\\u043a\\u0440\\u044b\\u0432\\u0430\\u044e\\u0449\\u0438\\u0435\\u0441\\u044f** \\u043e\\u043a\\u043d\\u0430 (stride=4096), \\u0431\\u0435\\u0437 packing-\\u0430\\u0440\\u0442\\u0435\\u0444\\u0430\\u043a\\u0442\\u043e\\u0432 (\\u043e\\u043a\\u043d\\u0430 \\u043f\\u043e \\u0433\\u0440\\u0430\\u043d\\u0438\\u0446\\u0430\\u043c \\u0441\\u043a\\u043b\\u0435\\u0435\\u043d\\u043d\\u043e\\u0433\\u043e \\u0442\\u0435\\u043a\\u0441\\u0442\\u0430 \\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u0443\\u044e\\u0442\\u0441\\u044f). \\u041c\\u0435\\u0442\\u043a\\u0438: (\\u0430) \\u0441\\u0432\\u043e\\u0434\\u043d\\u044b\\u0439 PPL \\u043f\\u043e \\u0432\\u0441\\u0435\\u043c \\u0442\\u043e\\u043a\\u0435\\u043d\\u0430\\u043c, (\\u0431) per-window \\u043f\\u043e\\u0442\\u0435\\u0440\\u0438 \\u2014 \\u043f\\u043e \\u043d\\u0438\\u043c bootstrap. E4: C4-val @2048.\\n\\n**Zero-shot.** lm-evaluation-harness, loglikelihood, \\u0437\\u0430\\u0434\\u0430\\u0447\\u0438 \\u0438 \\u043c\\u0435\\u0442\\u0440\\u0438\\u043a\\u0438: piqa (acc), hellaswag (acc, acc_norm), arc-easy (acc, acc_norm), arc-challenge (acc, acc_norm), winogrande (acc), openbookqa (acc, acc_norm); \\u0447\\u0438\\u0441\\u043b\\u043e few-shot \\u2014 \\u0434\\u0435\\u0444\\u043e\\u043b\\u0442\\u044b \\u0445\\u0430\\u0440\\u043d\\u0435\\u0441\\u0441\\u0430, \\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u0443\\u044e\\u0442\\u0441\\u044f \\u0432 \\u043a\\u043e\\u043d\\u0444\\u0438\\u0433\\u0435-\\u0445\\u044d\\u0448\\u0435; \\u0441\\u0432\\u043e\\u0434\\u043d\\u0430\\u044f \\u043c\\u0435\\u0442\\u0440\\u0438\\u043a\\u0430 \\u2014 \\u0441\\u0440\\u0435\\u0434\\u043d\\u0438\\u0439 acc_norm \\u043f\\u043e 6 \\u0437\\u0430\\u0434\\u0430\\u0447\\u0430\\u043c. **\\u0428\\u0430\\u0431\\u043b\\u043e\\u043d \\u043f\\u0440\\u043e\\u043c\\u043f\\u0442\\u0430:** \\u0447\\u0430\\u0442-\\u0448\\u0430\\u0431\\u043b\\u043e\\u043d \\u0442\\u043e\\u043a\\u0435\\u043d\\u0438\\u0437\\u0430\\u0442\\u043e\\u0440\\u0430 Phi-3 \\u0438\\u0437 hf, \\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u044b\\u0439 (\\u043f\\u0443\\u0441\\u0442\\u043e\\u0439/\\u043a\\u043e\\u043d\\u0441\\u0442\\u0430\\u043d\\u0442\\u043d\\u044b\\u0439 system), \\u043e\\u0434\\u0438\\u043d\\u0430\\u043a\\u043e\\u0432 \\u0434\\u043b\\u044f \\u0432\\u0441\\u0435\\u0445 \\u044f\\u0447\\u0435\\u0435\\u043a \\u0438 \\u0432\\u0441\\u0435\\u0445 \\u043f\\u043e\\u0432\\u0442\\u043e\\u0440\\u043e\\u0432; raw-\\u0448\\u0430\\u0431\\u043b\\u043e\\u043d \\u0441\\u043e\\u0445\\u0440\\u0430\\u043d\\u044f\\u0435\\u0442\\u0441\\u044f \\u0432 \\u0430\\u0440\\u0442\\u0435\\u0444\\u0430\\u043a\\u0442\\u044b. Temperature=0, generation \\u043d\\u0435 \\u0438\\u0441\\u043f\\u043e\\u043b\\u044c\\u0437\\u0443\\u0435\\u0442\\u0441\\u044f \\u0432 \\u044f\\u0434\\u0440\\u0435.\\n\\n## 3. \\u041f\\u0440\\u0435\\u0434\\u0432\\u0430\\u0440\\u0438\\u0442\\u0435\\u043b\\u044c\\u043d\\u044b\\u0435 \\u0433\\u0435\\u0439\\u0442\\u044b (\\u0437\\u0430\\u043f\\u0443\\u0441\\u043a \\u0441\\u0435\\u0442\\u043a\\u0438 \\u0437\\u0430\\u043f\\u0440\\u0435\\u0449\\u0451\\u043d \\u0431\\u0435\\u0437 \\u043f\\u0440\\u043e\\u0445\\u043e\\u0436\\u0434\\u0435\\u043d\\u0438\\u044f \\u0432\\u0441\\u0435\\u0445)\\n\\n- **G1. Rotation-equivalence.** FP16 vs FP16+\\u0432\\u0441\\u0435 \\u0440\\u043e\\u0442\\u0430\\u0446\\u0438\\u0438 (rotation-only no-quant) \\u043d\\u0430 \\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u043e\\u0439 \\u043f\\u043e\\u0434\\u0432\\u044b\\u0431\\u043e\\u0440\\u043a\\u0435 100 \\u043e\\u043a\\u043e\\u043d \\u00d7 4096 \\u0442\\u043e\\u043a\\u0435\\u043d\\u043e\\u0432 (seed=0): \\u0442\\u0440\\u0435\\u0431\\u0443\\u0435\\u043c mean KL(FP16\\u2016rot) < 1e-3 \\u0438 \\u0441\\u043e\\u0432\\u043f\\u0430\\u0434\\u0435\\u043d\\u0438\\u0435 argmax > 99.9% \\u043d\\u0430 bf16. \\u041f\\u0440\\u043e\\u0432\\u0430\\u043b \\u2192 \\u043e\\u0448\\u0438\\u0431\\u043a\\u0430 \\u0440\\u0435\\u0430\\u043b\\u0438\\u0437\\u0430\\u0446\\u0438\\u0438 \\u0440\\u0435\\u0446\\u0435\\u043f\\u0442\\u0430 (\\u0433\\u043b\\u0430\\u0432\\u043d\\u044b\\u0439 \\u0440\\u0438\\u0441\\u043a \\u2014 head_dim=96), \\u0441\\u0435\\u0442\\u043a\\u0430 \\u043d\\u0435 \\u0437\\u0430\\u043f\\u0443\\u0441\\u043a\\u0430\\u0435\\u0442\\u0441\\u044f.\\n- **G2. FP16 zero-shot \\u043f\\u0438\\u043b\\u043e\\u0442.** FP16 \\u043d\\u0430 6 \\u0437\\u0430\\u0434\\u0430\\u0447\\u0430\\u0445: \\u043d\\u0438 \\u043e\\u0434\\u043d\\u0430 \\u0437\\u0430\\u0434\\u0430\\u0447\\u0430 \\u043d\\u0435 \\u043d\\u0438\\u0436\\u0435 \\u0441\\u043b\\u0443\\u0447\\u0430\\u0439\\u043d\\u043e\\u0433\\u043e \\u0443\\u0440\\u043e\\u0432\\u043d\\u044f \\u0438 \\u0437\\u043d\\u0430\\u0447\\u0435\\u043d\\u0438\\u044f \\u0432 \\u043f\\u0440\\u0430\\u0432\\u0434\\u043e\\u043f\\u043e\\u0434\\u043e\\u0431\\u043d\\u043e\\u043c \\u0434\\u043b\\u044f Phi-3-mini \\u0434\\u0438\\u0430\\u043f\\u0430\\u0437\\u043e\\u043d\\u0435 (\\u0442\\u043e\\u0447\\u043d\\u044b\\u0439 \\u043e\\u0436\\u0438\\u0434\\u0430\\u0435\\u043c\\u044b\\u0439 \\u0438\\u043d\\u0442\\u0435\\u0440\\u0432\\u0430\\u043b \\u2014 unknown, \\u043a\\u0440\\u0438\\u0442\\u0435\\u0440\\u0438\\u0439 \\u00ab\\u043d\\u0435\\u0442 \\u0441\\u0445\\u043b\\u043e\\u043f\\u0430\\u00bb, \\u0430 \\u043d\\u0435 \\u043a\\u043e\\u043d\\u043a\\u0440\\u0435\\u0442\\u043d\\u043e\\u0435 \\u0447\\u0438\\u0441\\u043b\\u043e).\\n- **G3. mlp_bias.** \\u0418\\u043d\\u044a\\u0435\\u043a\\u0446\\u0438\\u043e\\u043d\\u043d\\u044b\\u0439 \\u0442\\u0435\\u0441\\u0442: forward \\u0441 \\u043d\\u0435\\u043d\\u0443\\u043b\\u0435\\u0432\\u044b\\u043c bias \\u0432 gate/up/down \\u0434\\u043e \\u0438 \\u043f\\u043e\\u0441\\u043b\\u0435 \\u043f\\u0440\\u0438\\u043c\\u0435\\u043d\\u0435\\u043d\\u0438\\u044f \\u043f\\u0430\\u0439\\u043f\\u043b\\u0430\\u0439\\u043d\\u0430 