u0438\\u0435).\\n\\n**\\u041a\\u0432\\u0430\\u043d\\u0442\\u0438\\u0437\\u0430\\u0442\\u043e\\u0440\\u044b (\\u043e\\u0431\\u0449\\u0438\\u0435 \\u0434\\u043b\\u044f \\u043e\\u0431\\u0435\\u0438\\u0445 \\u0432\\u0435\\u0442\\u043e\\u043a):** \\u0441\\u0438\\u043c\\u043c\\u0435\\u0442\\u0440\\u0438\\u0447\\u043d\\u044b\\u0439 \\u043a\\u0432\\u0430\\u043d\\u0442, **group-size 128**, per-group scale, \\u043e\\u0434\\u0438\\u043d\\u0430\\u043a\\u043e\\u0432\\u0430\\u044f \\u043a\\u0430\\u043b\\u0438\\u0431\\u0440\\u043e\\u0432\\u043a\\u0430, \\u043e\\u0434\\u0438\\u043d\\u0430\\u043a\\u043e\\u0432\\u044b\\u0439 \\u043d\\u0430\\u0431\\u043e\\u0440/seq-len eval. GPTQ: Hessian \\u0441 \\u043a\\u0430\\u043b\\u0438\\u0431\\u0440\\u043e\\u0432\\u043a\\u0438, damping=0.01 (\\u26a0\\ufe0f \\u043a\\u043e\\u043d\\u0432\\u0435\\u043d\\u0446\\u0438\\u044f, \\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043e \\u0434\\u043e \\u0437\\u0430\\u043f\\u0443\\u0441\\u043a\\u0430), act-order=off (\\u0434\\u0435\\u0442\\u0435\\u0440\\u043c\\u0438\\u043d\\u0438\\u0437\\u043c \\u0438 \\u043f\\u0440\\u043e\\u0441\\u0442\\u043e\\u0442\\u0430; \\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043e), fp32-\\u0430\\u043a\\u043a\\u0443\\u043c\\u0443\\u043b\\u044f\\u0446\\u0438\\u044f. RTN: per-group round-to-nearest \\u043d\\u0430 \\u0440\\u043e\\u0442\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u044b\\u0445 \\u0432\\u0435\\u0441\\u0430\\u0445; \\u043a\\u0430\\u043b\\u0438\\u0431\\u0440\\u043e\\u0432\\u043a\\u0430 RTN \\u043d\\u0435 \\u043d\\u0443\\u0436\\u043d\\u0430, \\u043d\\u043e \\u0442\\u043e\\u0442 \\u0436\\u0435 \\u043d\\u0430\\u0431\\u043e\\u0440 \\u0440\\u0435\\u0437\\u0435p\\u0432\\u0438\\u0440\\u0443\\u0435\\u0442\\u0441\\u044f \\u0434\\u043b\\u044f \\u0441\\u0442\\u0430\\u0442\\u0438\\u0441\\u0442\\u0438\\u043a \\u0430\\u043a\\u0442\\u0438\\u0432\\u0430\\u0446\\u0438\\u0439 (\\u0434\\u043b\\u044f E3).\\n\\n**\\u041a\\u0430\\u043b\\u