438 \\u043c\\u0438\\u043d\\u0443\\u0442 \\u043d\\u0430 \\u044f\\u0447\\u0435\\u0439\\u043a\\u0443. WikiText-2 test \\u2248 245k \\u0442\\u043e\\u043a\\u0435\\u043d\\u043e\\u0432 \\u26a0\\ufe0f \\u2192 ~60 \\u043e\\u043a\\u043e\\u043d \\u00d7 7 \\u044f\\u0447\\u0435\\u0435\\u043a \\u2014 \\u043f\\u0440\\u0435\\u043d\\u0435\\u0431\\u0440\\u0435\\u0436\\u0438\\u043c\\u043e. Zero-shot \\u0445\\u0430\\u0440\\u043d\\u0435\\u0441\\u0441 \\u2014 \\u0441\\u0430\\u043c\\u0430\\u044f \\u0434\\u043e\\u0440\\u043e\\u0433\\u0430\\u044f \\u0447\\u0430\\u0441\\u0442\\u044c, ~2\\u20134 GPU-\\u0447 \\u043d\\u0430 \\u044f\\u0447\\u0435\\u0439\\u043a\\u0443 (hellaswag \\u043b\\u0438\\u0434\\u0438\\u0440\\u0443\\u0435\\u0442). **\\u041e\\u0446\\u0435\\u043d\\u043a\\u0430 \\u044f\\u0434\\u0440\\u0430: \\u22481 GPU-\\u0441\\u0443\\u0442\\u043a\\u0438; \\u0441\\u043e \\u0432\\u0441\\u0435\\u043c\\u0438 extensions: +3\\u20135.** \\u0422\\u0435\\u043a\\u0443\\u0449\\u0430\\u044f \\u0441\\u0440\\u0435\\u0434\\u0430 (\\u0431\\u0435\\u0437 \\u0441\\u0435\\u0442\\u0438/GPU/torch) \\u0433\\u043e\\u0434\\u0438\\u0442\\u0441\\u044f \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u043d\\u0430 \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d, code-review \\u0438 unit-\\u0442\\u0435\\u0441\\u0442\\u044b G3/G4 \\u043d\\u0430 toy-\\u0432\\u0435\\u0441\\u0430\\u0445.\\n\\n**\\u041e\\u0447\\u0435\\u0440\\u0435\\u0434\\u044c \\u0441\\u043e\\u043a\\u0440\\u0430\\u0449\\u0435\\u043d\\u0438\\u0439 \\u043f\\u0440\\u0438 \\u0436\\u0451\\u0441\\u0442\\u043a\\u043e\\u043c \\u0431\\u044e\\u0434\\u0436\\u0435\\u0442\\u0435 (\\u0441\\u0432\\u0435\\u0440\\u0445\\u0443 \\u0432\\u043d\\u0438\\u0437):** (1) E5 GSM8K, E4 C4, E3 W4A4; (2) E1 QuaRot-off \\u0441\\u043e\\u043a\\u0440\\u0430\\u0449\\u0430\\u0435\\u0442\\u0441\\u044f \\u0434\\u043e W4/W6; (3) zero-shot \\u0434\\u043e hellaswag+piqa+arc-easy+winogrande; (4) PPL \\u043e\\u0441\\u0442\\u0430\\u0451\\u0442\\u0441\\u044f WikiText-2@4096. **\\u042f\\u0434\\u0440\\u043e (6 QuaRot-on \\u044f\\u0447\\u0435\\u0435\\u043a + FP16 + \\u0433\\u0435\\u0439\\u0442\\u044b G1\\u2013G4) \\u043d\\u0435 \\u0441\\u043e\\u043a\\u0440\\u0430\\u0449\\u0430\\u0435\\u0442\\u0441\\u044f \\u043d\\u0438 \\u043f\\u0440\\u0438 \\u043a\\u0430\\u043a\\u043e\\u043c \\u0431\\u044e\\u0434\\u0436\\u0435\\u0442\\u0435** \\u2014 \\u044d\\u0442\\u043e \\u043c\\u0438\\u043d\\u0438\\u043c\\u0443\\u043c \\u0434\\u043b\\u044f \\u043e\\u0442\\u0432\\u0435\\u0442\\u0430 \\u043d\\u0430 \\u0432\\u043e\\u043f\\u0440\\u043e\\u0441.\\n\\n**Assumptions (\\u043f\\u0435\\u0440\\u0435\\u043d\\u0435\\u0441\\u0435\\u043d\\u044b \\u0431\\u0435\\u0437 \\u0441\\u043c\\u044f\\u0433\\u0447\\u0435\\u043d\\u0438\\u044f):** \\u043a\\u0430\\u043b\\u0438\\u0431\\u0440\\u043e\\u0432\\u043a\\u0430 C4 128\\u00d72048 \\u2014 \\u043f\\u043e \\u043a\\u043e\\u043d\\u0432\\u0435\\u043d\\u0446\\u0438\\u0438, \\u043d\\u0435 \\u0438\\u0437 \\u043f\\u0440\\u043e\\u0432\\u0435\\u0440\\u0435\\u043d\\u043d\\u043e\\u0433\\u043e \\u0438\\u0441\\u0442\\u043e\\u0447\\u043d\\u0438\\u043a\\u0430; group-size 128, \\u0441\\u0438\\u043c\\u043c\\u0435\\u0442\\u0440\\u0438\\u0447\\u043d\\u044b\\u0439 \\u043a\\u0432\\u0430\\u043d\\u0442 \\u2014 \\u043a\\u043e\\u043d\\u0432\\u0435\\u043d\\u0446\\u0438\\u044f; \\u0440\\u0435\\u0446\\u0435\\u043f\\u0442 R1\\u2013R4 \\u043f\\u0435\\u0440\\u0435\\u043d\\u043e\\u0441\\u0438\\u043c \\u043d\\u0430 Phi-3 \\u0441 \\u0431\\u043b\\u043e\\u0447\\u043d\\u043e\\u0439 \\u0430\\u0434\\u0430\\u043f\\u0442\\u0430\\u0446\\u0438\\u0435\\u0439 H64\\u2295H32 \\u2014 \\u043f\\u0440\\u043e\\u0432\\u0435\\u0440\\u044f\\u0435\\u0442\\u0441\\u044f G1, \\u043d\\u0435 \\u043f\\u0440\\u0435\\u0434\\u043f\\u043e\\u043b\\u0430\\u0433\\u0430\\u0435\\u0442\\u0441\\u044f \\u0432\\u0435\\u0440\\u043d\\u044b\\u043c; PyTorch fake-quant \\u0431\\u0435\\u0437 CUDA-\\u044f\\u0434\\u0435\\u0440 QvQ \\u2014 \\u0438\\u0437\\u043c\\u0435\\u0440\\u044f\\u0435\\u0442\\u0441\\u044f \\u0442\\u043e\\u0447\\u043d\\u043e\\u0441\\u0442\\u044c \\u0430\\u043b\\u0433\\u043e\\u0440\\u0438\\u0442\\u043c\\u0430, \\u043d\\u0435 \\u043f\\u0440\\u043e\\u0438\\u0437\\u0432\\u043e\\u0434\\u0438\\u0442\\u0435\\u043b\\u044c\\u043d\\u043e\\u0441\\u0442\\u044c \\u044f\\u0434\\u0435\\u0440; \\u0447\\u0438\\u0441\\u043b\\u0430 \\u043a\\u043e\\u043d\\u0444\\u0438\\u0433\\u0430 Phi-3 \\u26a0\\ufe0f \\u043f\\u043e \\u043f\\u0430\\u043c\\u044f\\u0442\\u0438; \\u0438\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0442-\\u043c\\u043e\\u0434\\u0435\\u043b\\u044c \\u043f\\u0440\\u0438\\u0433\\u043e\\u0434\\u043d\\u0430 \\u0434\\u043b\\u044f loglikelihood-\\u0437\\u0430\\u0434\\u0430\\u0447 \\u2014 \\u043f\\u0440\\u043e\\u0432\\u0435\\u0440\\u044f\\u0435\\u0442\\u0441\\u044f G2; \\u0440\\u0435\\u0430\\u043b\\u044c\\u043d\\u044b\\u0439 \\u043f\\u0440\\u043e\\u0433\\u043e\\u043d \\u043f\\u0440\\u0435\\u0434\\u043f\\u043e\\u043b\\u0430\\u0433\\u0430\\u0435\\u0442 1\\u00d780\\u0413\\u0411 GPU.\\n\\n**Unknowns (\\u043d\\u0435 \\u0437\\u0430\\u043a\\u0440\\u044b\\u0442\\u044b, \\u043d\\u0435 \\u0432\\u044b\\u0434\\u0443\\u043c\\u0430\\u043d\\u044b):** \\u043f\\u043e\\u0434\\u0434\\u0435\\u0440\\u0436\\u043a\\u0430 Phi-3 \\u043e\\u0444\\u0438\\u0446\\u0438\\u0430\\u043b\\u044c\\u043d\\u044b\\u043c \\u043a\\u043e\\u0434\\u043e\\u043c QuaRot (\\u0432\\u0435\\u0440\\u043e\\u044f\\u0442\\u043d\\u043e \\u00ab\\u043d\\u0435\\u0442\\u00bb, \\u043d\\u0435\\u043f\\u0440\\u043e\\u0432\\u0435\\u0440\\u044f\\u0435\\u043c\\u043e \\u0432 \\u0441\\u0440\\u0435\\u0434\\u0435); \\u0442\\u043e\\u0447\\u043d\\u044b\\u0439 eval-\\u043f\\u0440\\u043e\\u0442\\u043e\\u043a\\u043e\\u043b \\u0441\\u0442\\u0430\\u0442\\u044c\\u0438 \\u0438 \\u0444\\u0430\\u043a\\u0442 \\u0440\\u0435\\u043f\\u043e\\u0440\\u0442\\u0438\\u043d\\u0433\\u0430 W6/W8-A16; \\u0447\\u0438\\u0441\\u043b\\u0435\\u043d\\u043d\\u0430\\u044f \\u043a\\u043e\\u0440\\u0440\\u0435\\u043a\\u0442\\u043d\\u043e\\u0441\\u0442\\u044c \\u0440\\u043e\\u0442\\u0430\\u0446\\u0438\\u0439 \\u043f\\u0440\\u0438 head_dim=96 \\u0434\\u043e G1; \\u043e\\u0431\\u0440\\u0430\\u0431\\u043e\\u0442\\u043a\\u0430 mlp_bias \\u0432 \\u043e\\u0444\\u0438\\u0446\\u0438\\u0430\\u043b\\u044c\\u043d\\u043e\\u043c \\u043f\\u0430\\u0439\\u043f\\u043b\\u0430\\u0439\\u043d\\u0435; \\u0444\\u0430\\u043a\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0439 \\u0431\\u044e\\u0434\\u0436\\u0435\\u0442 \\u043f\\u0440\\u043e\\u0433\\u043e\\u043d\\u0430. \\u041e\\u0436\\u0438\\u0434\\u0430\\u0435\\u043c\\u044b\\u0445 \\u0437\\u043d\\u0430\\u0447\\u0435\\u043d\\u0438\\u0439 PPL/accuracy \\u043d\\u0438\\u0433\\u0434\\u0435 \\u043d\\u0435 \\u043f\\u0440\\u0438\\u0432\\u043e\\u0434\\u0438\\u0442\\u0441\\u044f \\u0438 \\u043f\\u0440\\u0438\\u0432\\u043e\\u0434\\u0438\\u0442\\u044c\\u0441\\u044f \\u043d\\u0435 \\u0431\\u0443\\u0434\\u0435\\u0442.\", \"evidence\": \"\\u0420\\u0430\\u0437\\u0432\\u0435\\u0434\\u043a\\u0430 (\\u043f\\u0440\\u0435\\u0434\\u044b\\u0434\\u0443\\u0449\\u0438\\u0439 \\u0442\\u0443\\u0440, \\u0437\\u0430\\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u0430): /workspace \\u0441\\u043e\\u0434\\u0435\\u0440\\u0436\\u0438\\u0442 \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e task.json (\\u00abDesign-only task; repositories and compute are not required\\u00bb); torch/transformers/lm-eval \\u043e\\u0442\\u0441\\u0443\\u0442\\u0441\\u0442\\u0432\\u0443\\u044e\\u0442, \\u0441\\u0435\\u0442\\u044c \\u0438 GPU \\u043d\\u0435\\u0434\\u043e\\u0441\\u0442\\u0443\\u043f\\u043d\\u044b (nvidia-smi \\u0431\\u0435\\u0437 \\u0434\\u0440\\u0430\\u0439\\u0432\\u0435\\u0440\\u0430), CUDA-\\u044f\\u0434\\u0440\\u0430 QuaRot \\u043d\\u0435\\u043f\\u0440\\u043e\\u0432\\u0435\\u0440\\u044f\\u0435\\u043c\\u044b; 224 CPU / ~2TB RAM / tmpfs 1TB. \\u0420\\u0435\\u0430\\u043b\\u044c\\u043d\\u044b\\u0445 \\u044d\\u043a\\u0441\\u043f\\u0435\\u0440\\u0438\\u043c\\u0435\\u043d\\u0442\\u043e\\u0432 \\u043d\\u0435 \\u0432\\u044b\\u043f\\u043e\\u043b\\u043d\\u044f\\u043b\\u043e\\u0441\\u044c; \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d \\u043e\\u043f\\u0438\\u0440\\u0430\\u0435\\u0442\\u0441\\u044f \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u043d\\u0430 \\u0438\\u043d\\u0441\\u043f\\u0435\\u043a\\u0446\\u0438\\u044e \\u043e\\u043a\\u0440\\u0443\\u0436\\u0435\\u043d\\u0438\\u044f \\u0438 \\u044f\\u0432\\u043d\\u044b\\u0435 assumptions. \\u0421\\u0442\\u0440\\u0443\\u043a\\u0442\\u0443\\u0440\\u0430 \\u043e\\u0442\\u0432\\u0435\\u0442\\u0430 \\u0441\\u043b\\u0435\\u0434\\u0443\\u0435\\u0442 \\u0443\\u0442\\u0432\\u0435\\u0440\\u0436\\u0434\\u0451\\u043d\\u043d\\u043e\\u043c\\u0443 \\u043f\\u043b\\u0430\\u043d\\u0443 \\u0438 \\u0442\\u0440\\u0451\\u043c \\u043f\\u043e\\u043f\\u0440\\u0430\\u0432\\u043a\\u0430\\u043c researcher'\\u0430: (1) \\u0433\\u043b\\u0430\\u0432\\u043d\\u0430\\u044f \\u0442\\u0430\\u0431\\u043b\\u0438\\u0446\\u0430 = 6 QuaRot-on \\u044f\\u0447\\u0435\\u0435\\u043a + FP16, \\u0432\\u0441\\u0451 \\u043e\\u0441\\u0442\\u0430\\u043b\\u044c\\u043d\\u043e\\u0435 \\u0432\\u044b\\u043d\\u0435\\u0441\\u0435\\u043d\\u043e \\u0432 extensions/ablations \\u0441 \\u043f\\u043e\\u043c\\u0435\\u0442\\u043a\\u043e\\u0439 \\u043e\\u0431 \\u043e\\u0431\\u044a\\u044f\\u0441\\u043d\\u044f\\u044e\\u0449\\u0435\\u0439 \\u0440\\u043e\\u043b\\u0438; (2) \\u0431\\u0438\\u0442\\u043d\\u043e\\u0441\\u0442\\u0438 INT4/6/8 \\u0438\\u0437 \\u043f\\u043e\\u0441\\u0442\\u0430\\u043d\\u043e\\u0432\\u043a\\u0438 \\u043e\\u0442\\u0434\\u0435\\u043b\\u0435\\u043d\\u044b \\u043e\\u0442 \\u0440\\u0435\\u0436\\u0438\\u043c\\u0430 \\u0430\\u043a\\u0442\\u0438\\u0432\\u0430\\u0446\\u0438\\u0439 (A16 \\u043f\\u043e \\u0443\\u043c\\u043e\\u043b\\u0447\\u0430\\u043d\\u0438\\u044e, A4 \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u043c\\u0430\\u0440\\u043a\\u0435\\u0440 \\u043d\\u0430 W4); (3) \\u0432 analysis plan \\u0437\\u0430\\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u044b \\u0438\\u043d\\u0432\\u0430\\u0440\\u0438\\u0430\\u043d\\u0442\\u044b RTN/GPTQ-\\u0432\\u0435\\u0442\\u043e\\u043a, bootstrap CI \\u043f\\u043e \\u043e\\u043a\\u043d\\u0430\\u043c, McNemar+Holm \\u043f\\u043e \\u0437\\u0430\\u0434\\u0430\\u0447\\u0430\\u043c, pre-registered \\u043f\\u043e\\u0440\\u043e\\u0433\\u0438 \\u043f\\u0440\\u0430\\u043a\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u043e\\u0439 \\u0437\\u043d\\u0430\\u0447\\u0438\\u043c\\u043e\\u0441\\u0442\\u0438 (\\u0394PPL\\u22650.2, \\u0394acc\\u22651.0 \\u043f.\\u043f.) \\u0438 W8-\\u0433\\u0435\\u0439\\u0442 \\u0432\\u0430\\u043b\\u0438\\u0434\\u043d\\u043e\\u0441\\u0442\\u0438, \\u0431\\u043b\\u043e\\u043a\\u0438\\u0440\\u0443\\u044e\\u0449\\u0438\\u0439 \\u043f\\u0435\\u0440\\u0435\\u043d\\u043e\\u0441 \\u0431\\u0430\\u0433\\u0430 \\u043d\\u0430 \\u0432\\u0435\\u0441\\u044c \\u0432\\u044b\\u0432\\u043e\\u0434. \\u0413\\u0435\\u0439\\u0442\\u044b G1\\u2013G4 \\u0437\\u0430\\u043a\\u0440\\u044b\\u0432\\u0430\\u044e\\u0442 \\u0433\\u043b\\u0430\\u0432\\u043d\\u044b\\u0439 \\u0442\\u0435\\u0445\\u043d\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0439 \\u0440\\u0438\\u0441\\u043a (head_dim=96 vs Hadamard-\\u0440\\u043e\\u0442\\u0430\\u0446\\u0438\\u0438, mlp_bias) \\u0434\\u043e \\u0437\\u0430\\u043f\\u0443\\u0441\\u043a\\u0430 \\u0441\\u0435\\u0442\\u043a\\u0438.\", \"assumptions\": [\"\\u041a\\u0430\\u043b\\u0438\\u0431\\u0440\\u043e\\u0432\\u043a\\u0430 GPTQ: C4, 128 \\u0441\\u044d\\u043c\\u043f\\u043b\\u043e\\u0432 \\u00d7 2048 \\u0442\\u043e\\u043a\\u0435\\u043d\\u043e\\u0432, seed=0 \\u2014 \\u043a\\u043e\\u043d\\u0432\\u0435\\u043d\\u0446\\u0438\\u044f, \\u043d\\u0435 \\u043f\\u0440\\u043e\\u0432\\u0435\\u0440\\u0435\\u043d\\u043d\\u044b\\u0439 \\u0444\\u0430\\u043a\\u0442 \\u0438\\u0437 \\u0441\\u0442\\u0430\\u0442\\u044c\\u0438\", \"Group-size 128, \\u0441\\u0438\\u043c\\u043c\\u0435\\u0442\\u0440\\u0438\\u0447\\u043d\\u044b\\u0439 per-group \\u043a\\u0432\\u0430\\u043d\\u0442, GPTQ damping=0.01, act-order=off \\u2014 \\u0437\\u0430\\u0444\\u0438\\u043a\\u0